import{_ as r,l,o as e,c as i,v as t,p,x as o,d,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"分治优化与四边形不等式","description":"","frontmatter":{"title":"分治优化与四边形不等式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dc-opt-quadrangle.md","filePath":"cs/dc-opt-quadrangle.md","lastUpdated":1789023840000}'),c={name:"cs/dc-opt-quadrangle.md"};function u(m,a,_,B,f,k){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="分治优化与四边形不等式" tabindex="-1">分治优化与四边形不等式 <a class="header-anchor" href="#分治优化与四边形不等式" aria-label="Permalink to &quot;分治优化与四边形不等式&quot;">​</a></h1><div class="epigraph"><p>决策单调：$opt[i]\\le opt[i+1]$ 则分治区间时 $opt$ 只在中点两侧搜；四边形不等式推出这单调，把 $O(n^2k)$ 降到 $O(n^2)$ 或 $O(kn\\log n)$。</p><footer>—— 据 Knuth, Optimum Binary Search Trees, 1971；Yao, Efficient Dynamic Programming, 1980 整理</footer></div><p>上一课<a href="/cs/convex-hull-trick">斜率优化</a>用直线凸包。另一类：\\(dp[i][k]=\\min_{j\\lt i} dp[j][k-1]+w(j+1,i)\\)。缺口是决策单调与四边形不等式 \\(w(a,c)+w(b,d)\\le w(a,d)+w(b,c)\\)（\\(a\\le b\\le c\\le d\\)）。不重写 CHT。后课 SMAWK 把单调完全矩阵的行最小线性求。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无结构时 \\(k\\) 层各 \\(O(n^2)\\)。若 \\(opt[i]\\le opt[i+1]\\)：算区间 \\([l,r]\\) 的 DP，先算中点 \\(m\\)，枚举 \\(j\\) 在 \\([opt[l-1],opt[r]]\\)，再递归左右，每层 \\(O(n)\\)，\\(O(n\\log n)\\) 每 \\(k\\)。四边形 + 区间包含单调 \\(\\Rightarrow\\) 决策单调（Yao）。</p><p>缺口是这套条件，不是凸包。</p><h3 id="knuth-优化更强" tabindex="-1">Knuth 优化更强 <a class="header-anchor" href="#knuth-优化更强" aria-label="Permalink to &quot;Knuth 优化更强&quot;">​</a></h3><p>Knuth：\\(opt[i][j-1]\\le opt[i][j]\\le opt[i+1][j]\\) 把区间 DP 从 \\(O(n^3)\\) 降到 \\(O(n^2)\\)。矩阵链、最优 BST 满足。后课专写。本课先分治层。</p><p><span class="marginnote">Yao 1980。Knuth 1971 最优 BST。后课 SMAWK 是完全单调矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证 \\(w\\) 四边形（或直接验证 \\(opt\\) 单调）。分治算一层。或按 Knuth 限制枚举范围。</p>',11)),(e(),p(h,null,{default:o(()=>[s(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%BB%A3%E4%BB%B7%20w%20%E5%9B%9B%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20MON%5B%22opt%20%E5%8D%95%E8%B0%83%22%5D%0A%20%20MON%20--%3E%20DC%5B%22%E5%88%86%E6%B2%BB%E4%B8%80%E5%B1%82%20O(n%20log%20n)%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>反例：不满足则不能用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更宽区间的最优切点不会跑到更窄的左边——交叉不等式保证换切点不亏。分治正确因 \\(m\\) 的 \\(opt\\) 给左右界。与 CHT：几何 vs 组合单调。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Knuth 区间 DP 全证明（下一课矩阵链收）。不写在线。后课默认：决策单调可分治。下一课 SMAWK。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四边形不等式 \\(\\Rightarrow\\) 决策单调。</li><li>分治把一层 \\(n^2\\) 变 \\(n\\log n\\)。</li><li>Knuth 区间 \\(O(n^2)\\) 后课。</li><li>出处：Knuth, 1971；Yao, 1980。</li></ul>',7))])}const E=r(c,[["render",u]]);export{b as __pageData,E as default};
